#!/usr/bin/python3

import pyrob.core as rob
import random
from pyrob.tasks import check_filled_cells, find_cells_to_be_filled

# Порядок вариантов: один раз перемешиваем при загрузке модуля — без повторений в пределах 0..3
_variant_order = list(range(4))
random.shuffle(_variant_order)

class Task:
    CHECKS = 3

    def load_level(self, n):
        idx = _variant_order[n % len(_variant_order)]
        if idx == 0:
            rob.set_field_size(3, 16)
            rob.set_cell_type(1, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 5, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 6, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 9, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 10, rob.CELL_TO_BE_FILLED)
            rob.goto(0, 3)
            rob.put_wall(bottom=True)
            rob.goto(0, 5)
            rob.put_wall(bottom=True)
            rob.goto(0, 6)
            rob.put_wall(bottom=True)
            rob.goto(0, 9)
            rob.put_wall(bottom=True)
            rob.goto(0, 10)
            rob.put_wall(bottom=True)
            rob.goto(1, 10)
            rob.put_wall(right=True)
            rob.set_parking_cell(1, 10)
            rob.goto(1, 0)
        elif idx == 1:
            rob.set_field_size(3, 16)
            rob.set_cell_type(1, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 5, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 6, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 9, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 10, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 11, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 13, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 14, rob.CELL_TO_BE_FILLED)
            rob.goto(0, 2)
            rob.put_wall(bottom=True)
            rob.goto(0, 5)
            rob.put_wall(bottom=True)
            rob.goto(0, 6)
            rob.put_wall(bottom=True)
            rob.goto(0, 9)
            rob.put_wall(bottom=True)
            rob.goto(0, 10)
            rob.put_wall(bottom=True)
            rob.goto(0, 11)
            rob.put_wall(bottom=True)
            rob.goto(0, 13)
            rob.put_wall(bottom=True)
            rob.goto(0, 14)
            rob.put_wall(bottom=True)
            rob.goto(1, 14)
            rob.put_wall(right=True)
            rob.set_parking_cell(1, 14)
            rob.goto(1, 0)
        elif idx == 2:
            rob.set_field_size(3, 16)
            rob.set_cell_type(1, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 4, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 7, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 10, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 11, rob.CELL_TO_BE_FILLED)
            rob.goto(0, 2)
            rob.put_wall(bottom=True)
            rob.goto(0, 3)
            rob.put_wall(bottom=True)
            rob.goto(0, 4)
            rob.put_wall(bottom=True)
            rob.goto(0, 7)
            rob.put_wall(bottom=True)
            rob.goto(0, 10)
            rob.put_wall(bottom=True)
            rob.goto(0, 11)
            rob.put_wall(bottom=True)
            rob.goto(1, 11)
            rob.put_wall(right=True)
            rob.set_parking_cell(1, 11)
            rob.goto(1, 0)
        elif idx == 3:
            rob.set_field_size(3, 13)
            rob.set_cell_type(1, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 5, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 6, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 9, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 10, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 11, rob.CELL_TO_BE_FILLED)
            rob.goto(0, 1)
            rob.put_wall(bottom=True)
            rob.goto(0, 2)
            rob.put_wall(bottom=True)
            rob.goto(0, 5)
            rob.put_wall(bottom=True)
            rob.goto(0, 6)
            rob.put_wall(bottom=True)
            rob.goto(0, 9)
            rob.put_wall(bottom=True)
            rob.goto(0, 10)
            rob.put_wall(bottom=True)
            rob.goto(0, 11)
            rob.put_wall(bottom=True)
            rob.goto(1, 11)
            rob.put_wall(right=True)
            rob.set_parking_cell(1, 11)
            rob.goto(1, 0)

        self.cells_to_fill = find_cells_to_be_filled()

    def check_solution(self):
        return check_filled_cells(self.cells_to_fill) and rob.is_parking_point()
